mapper.select:
SELECT e.id, e.exam_name AS examName, e.paper_id AS paperId, p.paper_name AS paperName, e.class_id AS classId, cl.class_name AS className, e.start_time AS startTime, e.end_time AS endTime, e.duration, e.status, u.real_name AS creatorName, (SELECT COUNT(*) FROM class_student cs WHERE cs.class_id = e.class_id) AS studentCount, (SELECT COUNT(*) FROM exam_record er WHERE er.exam_id = e.id AND er.status = 'SUBMITTED') AS submittedCount, e.create_time AS createTime FROM exam e LEFT JOIN paper p ON e.paper_id = p.id LEFT JOIN class cl ON e.class_id = cl.id LEFT JOIN user u ON e.creator_id = u.id
AND e.creator_id = #{creatorId}
AND e.status = #{status}
ORDER BY e.create_time DESC
